import{_ as n,a0 as l,w as r,s as p,I as e,x as s,a1 as i,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 Fedora Linux 上安裝 VLC | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安裝 VLC | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安裝 VLC | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安裝 VLC | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210725 How to Install VLC on Fedora Linux","title":"如何在 Fedora Linux 上安裝 VLC","tag":"202107","desc":""},"relativePath":"202107/20210725 How to Install VLC on Fedora Linux.md","filePath":"[post].md"}'),u={name:"202107/20210725 How to Install VLC on Fedora Linux.md"};function f(g,t,m,h,C,L){const a=l("Link");return r(),p("div",null,[t[18]||(t[18]=e("h1",{id:"如何在-fedora-linux-上安裝-vlc",tabindex:"-1"},[s("如何在 Fedora Linux 上安裝 VLC "),e("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安裝-vlc","aria-label":"Permalink to “如何在 Fedora Linux 上安裝 VLC”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/31/215634thkmiihq1limel4i.jpg",alt:""})],-1)),t[20]||(t[20]=e("p",null,"如果你剛剛安裝了 Fedora，現在想在上面安裝你最喜歡的視頻播放器 VLC，你可能不會在軟件中心找到它。至少不會立即找到。",-1)),e("p",null,[t[1]||(t[1]=s("出於只有它的開發者知道的原因，Fedora 既沒有安裝 ",-1)),i(a,{href:"https://www.videolan.org/"},{default:o(()=>[...t[0]||(t[0]=[s("VLC",-1)])]),_:1}),t[2]||(t[2]=s("，也不包括在 Fedora 官方倉庫中。",-1))]),t[21]||(t[21]=d('<p>那麼，你如何在 Fedora 上安裝 VLC 呢？很簡單。RPM Fusion 是你的朋友。讓我告訴你詳細的步驟。</p><h3 id="在-fedora-linux-上安裝-vlc" tabindex="-1">在 Fedora Linux 上安裝 VLC <a class="header-anchor" href="#在-fedora-linux-上安裝-vlc" aria-label="Permalink to “在 Fedora Linux 上安裝 VLC”">​</a></h3><p>在這裏使用命令列會更容易。你也可以使用圖形化的方法。我將在後面討論它。</p><p>打開終端，使用下面的命令來添加和啓用包含 VLC 包的 RPM Fusion 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://mirrors.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>當被要求確認添加新倉庫時按 <code>Y</code>。接下來，使用 DNF 命令安裝 VLC：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install vlc</span></span></code></pre></div><p>它將在 Fedora 中從 RPM Fusion 倉庫中安裝 VLC，並從不同的倉庫中安裝一些額外的依賴項。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/07/installing-vlc-fedora-800x422.webp" alt="Installing VLC in Fedora with DNF command"></p><p>安裝後，你可以在應用程序菜單中搜索 VLC，或者在“活動區”中搜索它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/07/vlc-fedora.png?resize=799%2C223&amp;ssl=1" alt="Search for VLC"></p><p>點擊、啓動並享受它。</p><h4 id="替代方法-從軟件中心安裝-vlc" tabindex="-1">替代方法：從軟件中心安裝 VLC <a class="header-anchor" href="#替代方法-從軟件中心安裝-vlc" aria-label="Permalink to “替代方法：從軟件中心安裝 VLC”">​</a></h4><p>當你已經啓用了 RPM Fusion 倉庫，你可以在軟件中心顯示這個倉庫的應用。要做到這一點，在終端使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf groupupdate core</span></span></code></pre></div><p>之後，打開軟件中心，搜索 VLC 並從那裏安裝。</p><p><img src="https://itsfoss.com/wp-content/uploads/2021/07/vlc-in-fedora-software-center-800x486.webp" alt="VLC in Fedora software center"></p><p>如果你有添加 FlatHub 倉庫，請避免安裝 Flatpak 版本的 VLC，因為它的大小大約是 1GB。RPM 版本的大小要小得多。</p><p>我希望你覺得這個快速教程對在 Fedora 上安裝 VLC 有幫助。享受吧。</p><hr>',20)),e("p",null,[t[4]||(t[4]=s("via: ",-1)),i(a,{href:"https://itsfoss.com/install-vlc-fedora/"},{default:o(()=>[...t[3]||(t[3]=[s("https://itsfoss.com/install-vlc-fedora/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=s("作者：",-1)),i(a,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[5]||(t[5]=[s("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:o(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const V=n(u,[["render",f]]);export{b as __pageData,V as default};
